// ===== @ingroup meos_cbuffer_base_srid =====
static void Gen_cbuffer_srid(DataChunk &args, ExpressionState &, Vector &result) {
    EnsureMeosThreadInitialized();
    UnaryExecutor::Execute<string_t, int32_t>(args.data[0], result, args.size(),
        [&](string_t in) {
            Cbuffer *v = BlobToCbuffer(in);
            int32_t r = cbuffer_srid(v);
            free(v);
            return r;
        });
}

static void Gen_cbuffer_set_srid(DataChunk &args, ExpressionState &, Vector &result) {
    EnsureMeosThreadInitialized();
    const idx_t rows = args.size();
    for (idx_t c = 0; c < 2; c++) args.data[c].Flatten(rows);
    auto in0 = FlatVector::GetData<string_t>(args.data[0]);
    auto in1 = FlatVector::GetData<int32_t>(args.data[1]);
    auto out = FlatVector::GetData<string_t>(result);
    auto &outv = FlatVector::Validity(result);
    for (idx_t i = 0; i < rows; i++) {
        if (!FlatVector::Validity(args.data[0]).RowIsValid(i)) { outv.SetInvalid(i); continue; }
        if (!FlatVector::Validity(args.data[1]).RowIsValid(i)) { outv.SetInvalid(i); continue; }
        Cbuffer *p0 = BlobToCbuffer(in0[i]);
        Cbuffer *r = cbuffer_set_srid(p0, in1[i]);
        free(p0);
        if (!r) { outv.SetInvalid(i); continue; }
        out[i] = CbufferToBlob(result, r);
    }
    if (rows == 1) result.SetVectorType(VectorType::CONSTANT_VECTOR);
}

static void Gen_cbuffer_transform(DataChunk &args, ExpressionState &, Vector &result) {
    EnsureMeosThreadInitialized();
    const idx_t rows = args.size();
    for (idx_t c = 0; c < 2; c++) args.data[c].Flatten(rows);
    auto in0 = FlatVector::GetData<string_t>(args.data[0]);
    auto in1 = FlatVector::GetData<int32_t>(args.data[1]);
    auto out = FlatVector::GetData<string_t>(result);
    auto &outv = FlatVector::Validity(result);
    for (idx_t i = 0; i < rows; i++) {
        if (!FlatVector::Validity(args.data[0]).RowIsValid(i)) { outv.SetInvalid(i); continue; }
        if (!FlatVector::Validity(args.data[1]).RowIsValid(i)) { outv.SetInvalid(i); continue; }
        Cbuffer *p0 = BlobToCbuffer(in0[i]);
        Cbuffer *r = cbuffer_transform(p0, in1[i]);
        free(p0);
        if (!r) { outv.SetInvalid(i); continue; }
        out[i] = CbufferToBlob(result, r);
    }
    if (rows == 1) result.SetVectorType(VectorType::CONSTANT_VECTOR);
}

static void Gen_cbuffer_transform_pipeline(DataChunk &args, ExpressionState &, Vector &result) {
    EnsureMeosThreadInitialized();
    const idx_t rows = args.size();
    for (idx_t c = 0; c < 4; c++) args.data[c].Flatten(rows);
    auto in0 = FlatVector::GetData<string_t>(args.data[0]);
    auto in1 = FlatVector::GetData<string_t>(args.data[1]);
    auto in2 = FlatVector::GetData<int32_t>(args.data[2]);
    auto in3 = FlatVector::GetData<bool>(args.data[3]);
    auto out = FlatVector::GetData<string_t>(result);
    auto &outv = FlatVector::Validity(result);
    for (idx_t i = 0; i < rows; i++) {
        if (!FlatVector::Validity(args.data[0]).RowIsValid(i)) { outv.SetInvalid(i); continue; }
        if (!FlatVector::Validity(args.data[1]).RowIsValid(i)) { outv.SetInvalid(i); continue; }
        if (!FlatVector::Validity(args.data[2]).RowIsValid(i)) { outv.SetInvalid(i); continue; }
        if (!FlatVector::Validity(args.data[3]).RowIsValid(i)) { outv.SetInvalid(i); continue; }
        Cbuffer *p0 = BlobToCbuffer(in0[i]);
        std::string s1 = in1[i].GetString();
        Cbuffer *r = cbuffer_transform_pipeline(p0, s1.c_str(), in2[i], in3[i]);
        free(p0);
        if (!r) { outv.SetInvalid(i); continue; }
        out[i] = CbufferToBlob(result, r);
    }
    if (rows == 1) result.SetVectorType(VectorType::CONSTANT_VECTOR);
}

static void Gen_cbuffer_transform_pipeline_v1(DataChunk &args, ExpressionState &, Vector &result) {
    EnsureMeosThreadInitialized();
    const idx_t rows = args.size();
    for (idx_t c = 0; c < 3; c++) args.data[c].Flatten(rows);
    auto in0 = FlatVector::GetData<string_t>(args.data[0]);
    auto in1 = FlatVector::GetData<string_t>(args.data[1]);
    auto in2 = FlatVector::GetData<int32_t>(args.data[2]);
    auto out = FlatVector::GetData<string_t>(result);
    auto &outv = FlatVector::Validity(result);
    for (idx_t i = 0; i < rows; i++) {
        if (!FlatVector::Validity(args.data[0]).RowIsValid(i)) { outv.SetInvalid(i); continue; }
        if (!FlatVector::Validity(args.data[1]).RowIsValid(i)) { outv.SetInvalid(i); continue; }
        if (!FlatVector::Validity(args.data[2]).RowIsValid(i)) { outv.SetInvalid(i); continue; }
        Cbuffer *p0 = BlobToCbuffer(in0[i]);
        std::string s1 = in1[i].GetString();
        Cbuffer *r = cbuffer_transform_pipeline(p0, s1.c_str(), in2[i], true);
        free(p0);
        if (!r) { outv.SetInvalid(i); continue; }
        out[i] = CbufferToBlob(result, r);
    }
    if (rows == 1) result.SetVectorType(VectorType::CONSTANT_VECTOR);
}

static void Gen_cbuffer_transform_pipeline_v2(DataChunk &args, ExpressionState &, Vector &result) {
    EnsureMeosThreadInitialized();
    const idx_t rows = args.size();
    for (idx_t c = 0; c < 2; c++) args.data[c].Flatten(rows);
    auto in0 = FlatVector::GetData<string_t>(args.data[0]);
    auto in1 = FlatVector::GetData<string_t>(args.data[1]);
    auto out = FlatVector::GetData<string_t>(result);
    auto &outv = FlatVector::Validity(result);
    for (idx_t i = 0; i < rows; i++) {
        if (!FlatVector::Validity(args.data[0]).RowIsValid(i)) { outv.SetInvalid(i); continue; }
        if (!FlatVector::Validity(args.data[1]).RowIsValid(i)) { outv.SetInvalid(i); continue; }
        Cbuffer *p0 = BlobToCbuffer(in0[i]);
        std::string s1 = in1[i].GetString();
        Cbuffer *r = cbuffer_transform_pipeline(p0, s1.c_str(), 0, true);
        free(p0);
        if (!r) { outv.SetInvalid(i); continue; }
        out[i] = CbufferToBlob(result, r);
    }
    if (rows == 1) result.SetVectorType(VectorType::CONSTANT_VECTOR);
}


